INSERT OR REPLACE INTO surveys (record_id, saved_at, updated_at, version, station, province, permit, fields_json, deleted_at) VALUES ('PM-202610150728124-2c3b', '2026-10-15T07:28:12.457Z', '2026-10-15T07:28:12.457Z', 1, 'หมู่ 8 ชัฎดงพลับ', 'กาญจนบุรี', 'อนุญาต', '{"permit":"อนุญาต","radioStatus":"ปกติ","receiveStatus":"ปกติ","transmitStatus":"ปกติ","powerStatus":"ปกติ","batteryStatus":"ปกติ","groundStatus":"ปกติ","station":"หมู่ 8 ชัฎดงพลับ","province":"กาญจนบุรี","district":"เลาขวัญ","subdistrict":"ทุ่งกระบ่ำ","installationPlace":"ที่ทำการบ้านผู้ใหญ่บ้าน","equipmentPlace":"ที่ทำการบ้านผู้ใหญ่บ้าน","contactName":"นางสาวน้ำทิพย์ เมียงชัย","contactPosition":"ผู้ใหญ่บ้าน","contactVillage":"หมู่ 8 ชัฎดงพลับ","contactPhone":"083-376-1745, ผช. 065-040-0790","visitDate":"2026-10-08","visitTime":"06:04","workObstacle":"ไม่มีอุปสรรค เจ้าของพื้นที่ให้ความร่วมมือและอำนวยความสะดวกในการเข้าตรวจสอบและทดสอบระบบเป็นอย่างดี","antennaCondition":"เสาอากาศติดตั้งภายนอกอาคารบริเวณลานข้างบ้าน โครงสร้างเสาตั้งตรง มั่นคงแข็งแรง สายยึดโยง (Guy Wire) ตึงปกติ สภาพสายนำสัญญาณเดินพาดเข้าสู่ตัวอาคารเรียบร้อย เปลือกหุ้มสายสมบูรณ์ ไม่แตกกรอบ และระยะห่างจากแนวกิ่งไม้โดยรอบอยู่ในเกณฑ์ปลอดภัย","siteCondition":"อุปกรณ์ติดตั้งอยู่ภายในตู้ Rack วางบนพื้นกระเบื้องภายในอาคาร (ที่ทำการบ้านผู้ใหญ่บ้าน) บริเวณใกล้ช่องเปิด/หน้าต่าง สภาพพื้นที่แห้ง สะอาด อากาศถ่ายเทได้สะดวก ไม่มีน้ำรั่วซึม และตู้ควบคุมระบบไฟฟ้าติดตั้งบนผนังเป็นระเบียบเรียบร้อย","summary":"เจ้าของพื้นที่แจ้งว่าระบบสื่อสารสามารถใช้งานรับ-ส่งสัญญาณได้ตามปกติ ไม่มีปัญหาขัดข้อง และไม่มีข้อร้องเรียนเพิ่มเติม","informantName":"นางสาวน้ำทิพย์ เมียงชัย","operatorName":"นายวัชระ มานะดี","photos":[],"recordId":"PM-202610150728124-2c3b"}', NULL);
