INSERT OR REPLACE INTO surveys (record_id, saved_at, updated_at, version, station, province, permit, fields_json, deleted_at) VALUES ('PM-202610150733048-e798', '2026-10-15T07:33:04.850Z', '2026-10-15T07:33:04.850Z', 1, 'หมู่ 2 หนองเค็ด', 'กาญจนบุรี', 'อนุญาต', '{"permit":"อนุญาต","radioStatus":"ปกติ","receiveStatus":"ปกติ","transmitStatus":"ปกติ","powerStatus":"ปกติ","batteryStatus":"ปกติ","groundStatus":"ปกติ","station":"หมู่ 2 หนองเค็ด","province":"กาญจนบุรี","district":"เลาขวัญ","subdistrict":"หนองนกแก้ว","installationPlace":"ที่ทำการบ้านผู้ใหญ่บ้าน","equipmentPlace":"ที่ทำการบ้านผู้ใหญ่บ้าน","contactName":"นางสาวฉวี โพธิ์หิรัญ","contactPosition":"ผู้ใหญ่บ้าน","contactVillage":"หมู่ 2 หนองเค็ด","contactPhone":"085-701-5890","visitDate":"2026-10-09","visitTime":"08:30","siteCondition":"อุปกรณ์จัดวางบนชั้นวางภายในอาคาร (ที่ทำการบ้านผู้ใหญ่บ้าน) สภาพพื้นที่แห้ง สะอาด เรียบร้อยดี อากาศถ่ายเทได้สะดวก ไม่มีแสงแดดส่องถึงตัวเครื่องโดยตรง และไม่มีจุดเสี่ยงน้ำรั่วซึม การจัดเก็บสายด้านหลังชั้นวางเป็นระเบียบ","antennaCondition":"เสาอากาศชนิดกายด์มาสต์ (Guyed Mast) ตั้งอยู่บริเวณข้างอาคาร โครงสร้างเสาตั้งตรง ทาสีสลับแดง-ขาวชัดเจน สายยึดโยง (Guy Wire) ตึงปกติ ไม่พบสนิมกัดกร่อนรุนแรง แนวสายนำสัญญาณเดินเข้าสู่อาคารเรียบร้อย เปลือกหุ้มสายสมบูรณ์ไม่กรอบแตก และบ่อกราวด์อยู่ในสภาพพร้อมใช้งาน","workObstacle":"ไม่มีอุปสรรค ผู้ใหญ่บ้านให้ความร่วมมือและอำนวยความสะดวกในการเข้าตรวจเช็กอุปกรณ์และจุดวัดระบบกราวด์เป็นอย่างดี","summary":"ผู้ใหญ่บ้านแจ้งว่าระบบวิทยุสื่อสารใช้งานรับ-ส่งสัญญาณได้ชัดเจนตามปกติ ระบบไฟฟ้าและอุปกรณ์สำรองไฟทำงานได้ดี ไม่มีปัญหาขัดข้อง และไม่มีข้อร้องเรียนเพิ่มเติม","operatorName":"นายวัชระ มานะดี","informantName":"นางสาวฉวี โพธิ์หิรัญ","photos":[],"recordId":"PM-202610150733048-e798"}', NULL);
