INSERT OR REPLACE INTO surveys (record_id, saved_at, updated_at, version, station, province, permit, fields_json, deleted_at) VALUES ('PM-202610150840368-5d76', '2026-10-15T08:40:36.864Z', '2026-10-15T08:40:36.864Z', 1, 'หมู่ 4 หนองจั่น', 'กาญจนบุรี', 'อนุญาต', '{"permit":"อนุญาต","radioStatus":"ปกติ","receiveStatus":"ปกติ","transmitStatus":"ปกติ","powerStatus":"ปกติ","batteryStatus":"ปกติ","groundStatus":"ปกติ","station":"หมู่ 4 หนองจั่น","province":"กาญจนบุรี","district":"เลาขวัญ","subdistrict":"หนองนกแก้ว","installationPlace":"ที่ทำการบ้านผู้ใหญ่บ้าน","equipmentPlace":"ที่ทำการบ้านผู้ใหญ่บ้าน","contactName":"นางสาวจุฑามาศ เวทยานนท์","contactPosition":"ผู้ใหญ่บ้าน","contactVillage":"หมู่ 4 หนองจั่น","contactPhone":"081-942-3643","visitDate":"2026-10-08","siteCondition":"อุปกรณ์จัดวางบนชั้นวางภายในอาคาร (ที่ทำการบ้านผู้ใหญ่บ้าน) บริเวณใกล้ช่องหน้าต่าง สภาพพื้นที่แห้ง สะอาด มีอากาศถ่ายเทได้สะดวก ไม่มีแสงแดดส่องกระทบตัวเครื่องโดยตรงและไม่มีจุดเสี่ยงน้ำรั่วซึม ตู้ควบคุมระบบไฟฟ้าหลักติดตั้งบนผนังอย่างปลอดภัย และการเดินสายสัญญาณร้อยท่อเข้าสู่อาคารเป็นระเบียบเรียบร้อย","antennaCondition":"เสาอากาศชนิดกายด์มาสต์ (Guyed Mast) ตั้งอยู่บริเวณลานภายนอกอาคาร โครงสร้างเสาตั้งตรง มั่นคงแข็งแรง สายยึดโยง (Guy Wire) ยึดแน่นตึงตามเกณฑ์ปกติ สายนำสัญญาณร้อยท่อเข้าตัวอาคารเรียบร้อย เปลือกหุ้มสายสมบูรณ์ไม่แตกลายงา บ่อพักระบบกราวด์อยู่ในสภาพสมบูรณ์พร้อมใช้งาน บริเวณโดยรอบมีต้นไม้และพุ่มไม้แต่ไม่พาดทับโครงสร้างเสาหรือแนวสายสัญญาณ","workObstacle":"ไม่มีอุปสรรค ผู้ใหญ่บ้านให้ความร่วมมือและอำนวยความสะดวกในการเข้าตรวจเช็กอุปกรณ์ ตู้ไฟ บ่อกราวด์ และโครงสร้างเสาอากาศเป็นอย่างดี","summary":"ผู้ใหญ่บ้านแจ้งว่าระบบวิทยุสื่อสารใช้งานรับ-ส่งสัญญาณได้ชัดเจนตามปกติ ระบบไฟฟ้าและแบตเตอรี่สำรองทำงานได้ดี ไม่มีปัญหาขัดข้องในการใช้งานประจำวัน และไม่มีข้อร้องเรียนเพิ่มเติม","informantName":"นางสาวจุฑามาศ เวทยานนท์","operatorName":"นายวัชระ มานะดี","photos":[],"recordId":"PM-202610150840368-5d76"}', NULL);
INSERT OR REPLACE INTO surveys (record_id, saved_at, updated_at, version, station, province, permit, fields_json, deleted_at) VALUES ('PM-202610150847170-dd69', '2026-10-15T08:47:17.087Z', '2026-10-15T08:47:17.087Z', 1, 'หมู่ 5 หนองขบ', 'กาญจนบุรี', 'อนุญาต', '{"permit":"อนุญาต","radioStatus":"ปกติ","receiveStatus":"ปกติ","transmitStatus":"ปกติ","powerStatus":"ปกติ","batteryStatus":"ปกติ","groundStatus":"ปกติ","station":"หมู่ 5 หนองขบ","province":"กาญจนบุรี","district":"เลาขวัญ","subdistrict":"หนองนกแก้ว","installationPlace":"ที่ทำการบ้านผู้ใหญ่บ้าน","equipmentPlace":"ที่ทำการบ้านผู้ใหญ่บ้าน","contactName":"นางสาวศิริมา ห้วยหงษ์ทอง","contactPosition":"ผู้ใหญ่บ้าน","contactVillage":"หมู่ 5 หนองขบ","contactPhone":"092-898-3949","visitDate":"2026-10-07","informantName":"นางสาวศิริมา ห้วยหงษ์ทอง","operatorName":"นายวัชระ มานะดี","siteCondition":"อุปกรณ์จัดวางบนโต๊ะ/ชั้นวางภายในอาคารที่ทำการบ้านผู้ใหญ่บ้าน สภาพพื้นที่แห้ง สะอาด อากาศถ่ายเทได้สะดวก ไม่มีแสงแดดส่องกระทบตัวเครื่องโดยตรง และไม่มีจุดเสี่ยงน้ำรั่วซึม การจัดเก็บสายไฟและสายสัญญาณด้านหลังเป็นระเบียบเรียบร้อย","antennaCondition":"เสาอากาศตั้งอยู่บริเวณภายนอกอาคาร โครงสร้างเสาตั้งตรง มั่นคงแข็งแรง ไม่พบการทรุดเอียง สายยึดโยง (Guy Wire) ตึงกระชับตามเกณฑ์ปกติ สภาพสายนำสัญญาณเดินเข้าสู่อาคารเรียบร้อย เปลือกหุ้มสายสมบูรณ์ไม่แตกลายงา และไม่มีกิ่งไม้ใหญ่พาดทับโครงสร้างเสา","workObstacle":"ไม่มีอุปสรรค ผู้ใหญ่บ้านให้ความร่วมมือและอำนวยความสะดวกในการเข้าตรวจสอบพื้นที่และตรวจเช็กระบบเป็นอย่างดี","summary":"ผู้ใหญ่บ้านแจ้งว่าระบบวิทยุสื่อสารใช้งานรับ-ส่งสัญญาณได้ชัดเจนตามปกติ ระบบไฟฟ้าและอุปกรณ์สำรองไฟทำงานได้ดี ไม่มีปัญหาขัดข้องในการประสานงาน และไม่มีข้อร้องเรียนเพิ่มเติม","photos":[],"recordId":"PM-202610150847170-dd69"}', NULL);
INSERT OR REPLACE INTO surveys (record_id, saved_at, updated_at, version, station, province, permit, fields_json, deleted_at) VALUES ('PM-202610150855267-f0f0', '2026-10-15T08:55:26.731Z', '2026-10-15T08:55:26.731Z', 1, 'หมู่ 9 หนองข่อย', 'กาญจนบุรี', 'อนุญาต', '{"permit":"อนุญาต","radioStatus":"ปกติ","receiveStatus":"ปกติ","transmitStatus":"ปกติ","powerStatus":"ปกติ","batteryStatus":"ปกติ","groundStatus":"ปกติ","station":"หมู่ 9 หนองข่อย","province":"กาญจนบุรี","district":"เลาขวัญ","subdistrict":"หนองนกแก้ว","installationPlace":"ที่ทำการบ้านผู้ใหญ่บ้าน","equipmentPlace":"ที่ทำการบ้านผู้ใหญ่บ้าน","contactName":"นายสุชาติ กลับสงวน","contactPosition":"ผู้ใหญ่บ้าน","contactVillage":"หมู่ 9 หนองข่อย","contactPhone":"086-049-8314","visitDate":"2026-10-08","informantName":"นายสุชาติ กลับสงวน","operatorName":"นายวัชระ มานะดี","siteCondition":"อุปกรณ์วิทยุคมนาคมจัดวางบนชั้นไม้วางของใกล้ประตูทางเข้าอาคาร (ที่ทำการบ้านผู้ใหญ่บ้าน) สภาพพื้นที่แห้งและมีอากาศถ่ายเทสะดวก ไม่อับทึบ การเดินสายไฟด้านหลังและเต้ารับต่อเข้ากับตู้ควบคุมบนผนัง บริเวณโดยรอบและชั้นด้านล่างมีเอกสารและสิ่งของจัดวางร่วมอยู่บ้างเล็กน้อย แต่ตัวเครื่องจัดวางมั่นคงและไม่บดบังช่องระบายอากาศ","antennaCondition":"โครงสร้างเสาอากาศและสายนำสัญญาณภายนอกอาคารติดตั้งมั่นคงแข็งแรง แนวสายนำสัญญาณเดินเข้าสู่อาคารเรียบร้อย เปลือกหุ้มสายสมบูรณ์ไม่แตกลายงา บ่อพักระบบกราวด์ (Master Ground Pit, AC Ground) สภาพสมบูรณ์พร้อมใช้งาน ฝาปิดแข็งแรง และตรวจวัดค่าความต้านทานดินได้ตามเกณฑ์มาตรฐาน","workObstacle":"ไม่มีอุปสรรค ผู้ใหญ่บ้านให้ความร่วมมือ อำนวยความสะดวกในการเข้าตรวจเช็กอุปกรณ์ ตรวจวัดระบบไฟ แบตเตอรี่ และบ่อกราวด์เป็นอย่างดี","summary":"ผู้ใหญ่บ้านแจ้งว่าระบบวิทยุสื่อสารใช้งานรับ-ส่งสัญญาณได้ชัดเจนตามปกติ ระบบไฟฟ้าและแบตเตอรี่สำรองพร้อมใช้งานดี ไม่มีปัญหาขัดข้อง และไม่มีข้อร้องเรียนเพิ่มเติม","photos":[],"recordId":"PM-202610150855267-f0f0"}', NULL);
INSERT OR REPLACE INTO surveys (record_id, saved_at, updated_at, version, station, province, permit, fields_json, deleted_at) VALUES ('PM-202610150858544-1939', '2026-10-15T08:58:54.486Z', '2026-10-15T08:58:54.486Z', 1, 'หมู่ 10 หนองมะสังข์', 'กาญจนบุรี', 'อนุญาต', '{"permit":"อนุญาต","radioStatus":"ปกติ","receiveStatus":"ปกติ","transmitStatus":"ปกติ","powerStatus":"ปกติ","batteryStatus":"ปกติ","groundStatus":"ปกติ","station":"หมู่ 10 หนองมะสังข์","province":"กาญจนบุรี","district":"เลาขวัญ","subdistrict":"หนองประดู่","installationPlace":"ที่ทำการบ้านผู้ใหญ่บ้าน","equipmentPlace":"ที่ทำการบ้านผู้ใหญ่บ้าน","contactName":"นางสาวธิดา พูนเงิน","contactPosition":"ผู้ใหญ่บ้าน","contactVillage":"หมู่ 10 หนองมะสังข์","contactPhone":"082-254-8406","visitDate":"2026-10-07","siteCondition":"อุปกรณ์วิทยุสื่อสาร Hytera จัดวางบนชั้นไม้ 3 ชั้นภายในอาคาร (ที่ทำการบ้านผู้ใหญ่บ้าน) และวางแบตเตอรี่สำรองไว้ที่ชั้นล่างสุด สภาพพื้นที่แห้ง ปลอดโปร่ง อากาศถ่ายเทได้สะดวก ไม่มีแสงแดดส่องกระทบตัวเครื่องโดยตรง การเดินสายไฟและสายนำสัญญาณเชื่อมต่อกับตู้จ่ายไฟ/เบรกเกอร์บนผนังเป็นระเบียบ ด้านข้างมีกล่องพัสดุและลังเครื่องดื่มวางอยู่บ้าง แต่ไม่บดบังช่องระบายความร้อนของตัวเครื่อง","antennaCondition":"เสาอากาศโครงเหล็กถัก (Self-Supporting Lattice Mast) ทาสีสลับแดง-ขาว ติดตั้งบนฐานรากคอนกรีตภายนอกอาคาร โครงสร้างเสาตั้งตรง มั่นคงแข็งแรงดี แนวสายนำสัญญาณเดินพาดเข้าสู่ตัวอาคารเรียบร้อย เปลือกหุ้มสายสมบูรณ์ไม่แตกลายงา บ่อพักระบบกราวด์ (Master Ground, RF Ground, AC Ground) อยู่ในสภาพสมบูรณ์พร้อมใช้งาน และวัดค่าความต้านทานดินผ่านเกณฑ์มาตรฐานอย่างดีเยี่ยมทุกจุด","workObstacle":"ไม่มีอุปสรรค ผู้ใหญ่บ้านให้ความร่วมมือและอำนวยความสะดวกในการเข้าตรวจเช็กอุปกรณ์ ทดสอบระบบสื่อสาร และจุดทดสอบระบบกราวด์เป็นอย่างดี","summary":"ผู้ใหญ่บ้านแจ้งว่าเครื่องวิทยุประจำสถานีทำงานได้ตามปกติ แต่มีความประสงค์ขอรับการสนับสนุนเครื่องวิทยุคมนาคมชนิดมือถือ (Handheld) เพิ่มเติม เพื่อความคล่องตัวในการติดต่อสื่อสารระหว่างลงพื้นที่ตรวจงาน","informantName":"นางสาวธิดา พูนเงิน","operatorName":"นายวัชระ มานะดี","photos":[],"recordId":"PM-202