INSERT OR REPLACE INTO surveys (record_id, saved_at, updated_at, version, station, province, permit, fields_json, deleted_at) VALUES ('PM-202610160053040-1301', '2026-10-16T00:53:04.082Z', '2026-10-16T00:53:04.082Z', 1, 'หมู่ 11 หนองตาเกิด', 'กาญจนบุรี', 'อนุญาต', '{"permit":"อนุญาต","radioStatus":"ปกติ","receiveStatus":"ปกติ","transmitStatus":"ปกติ","powerStatus":"ปกติ","batteryStatus":"ปกติ","groundStatus":"ปกติ","station":"หมู่ 11 หนองตาเกิด","province":"กาญจนบุรี","district":"เลาขวัญ","subdistrict":"หนองประดู่","installationPlace":"ที่ทำการบ้านผู้ใหญ่บ้าน","equipmentPlace":"ที่ทำการบ้านผู้ใหญ่บ้าน","contactName":"นายเจ็ก จีนจันทร์","contactPosition":"ผู้ใหญ่บ้าน","contactVillage":"หมู่ 11 หนองตาเกิด","contactPhone":"065-295-7164","visitDate":"2026-10-09","informantName":"นายเจ็ก จีนจันทร์","operatorName":"นายวัชระ มานะดี","siteCondition":"อุปกรณ์วิทยุสื่อสาร Hytera จัดวางบนชั้นไม้ 3 ชั้น บริเวณมุมห้องริมหน้าต่างภายในอาคาร สภาพพื้นที่แห้ง สะอาด อากาศถ่ายเทสะดวกและมีแสงสว่างเพียงพอ ชั้นล่างติดตั้งแบตเตอรี่สำรอง (Transpower) อย่างมั่นคง เต้ารับไฟฟ้า AC และสายไฟหลักร้อยท่อแนบผนังเป็นระเบียบเรียบร้อย แรงดันไฟฟ้าปกติ ไม่พบจุดเสี่ยงน้ำรั่วซึม","antennaCondition":"สาอากาศโครงเหล็กถัก (Self-Supporting Lattice Mast) ทาสีสลับแดง-ขาว ติดตั้งบนฐานรากคอนกรีตภายนอกอาคาร โครงสร้างเสาตั้งตรง มั่นคงแข็งแรงดี แนวสายนำสัญญาณเดินเข้าสู่อาคารเรียบร้อย เปลือกหุ้มสายสมบูรณ์ไม่แตกลายงา และไม่อยู่ในระยะกีดขวางของแนวสายไฟแรงต่ำภายนอก บ่อพักระบบกราวด์ทุกจุด (Master Ground, AC Ground, RF Ground) สภาพสมบูรณ์และวัดค่าความต้านทานดินผ่านเกณฑ์มาตรฐานอย่างดีเยี่ยม","workObstacle":"ไม่มีอุปสรรค การเดินทางเข้าพื้นที่สะดวก เจ้าของพื้นที่ให้ความร่วมมือและอำนวยความสะดวกในการเข้าตรวจเช็กอุปกรณ์ ตรวจวัดระบบไฟฟ้า และจุดทดสอบระบบกราวด์เป็นอย่างดี","summary":"เจ้าของพื้นที่แจ้งว่าระบบวิทยุสื่อสารใช้งานรับ-ส่งสัญญาณได้ชัดเจนตามปกติ ระบบไฟฟ้าและแบตเตอรี่สำรองทำงานได้สมบูรณ์ดี ไม่มีปัญหาขัดข้องในการประสานงาน และไม่มีข้อร้องเรียนเพิ่มเติม","photos":[],"recordId":"PM-202610160053040-1301"}', NULL);
INSERT OR REPLACE INTO surveys (record_id, saved_at, updated_at, version, station, province, permit, fields_json, deleted_at) VALUES ('PM-202610160121171-8854', '2026-10-16T01:21:17.196Z', '2026-10-16T01:21:17.196Z', 1, 'หมู่ 3 ตลุงเหนือ', 'กาญจนบุรี', 'อนุญาต', '{"permit":"อนุญาต","radioStatus":"ปกติ","receiveStatus":"ปกติ","transmitStatus":"ปกติ","powerStatus":"ปกติ","batteryStatus":"ปกติ","groundStatus":"ปกติ","station":"หมู่ 3 ตลุงเหนือ","province":"กาญจนบุรี","district":"เลาขวัญ","subdistrict":"หนองประดู่","installationPlace":"ที่ทำการบ้านผู้ใหญ่บ้าน","equipmentPlace":"ที่ทำการบ้านผู้ใหญ่บ้าน","contactName":"นายเสรีย์ หงษ์โต","contactPosition":"ผู้ใหญ่บ้าน","contactVillage":"หมู่ 3 ตลุงเหนือ","contactPhone":"080-075-5751","visitDate":"2026-10-07","informantName":"นายเสรีย์ หงษ์โต","operatorName":"นายวัชระ มานะดี","siteCondition":"อุปกรณ์วิทยุสื่อสาร Hytera จัดวางบนชั้นไม้ 3 ชั้นภายในอาคารอย่างมั่นคง ด้านล่างติดตั้งแบตเตอรี่สำรอง (Transpower) สภาพพื้นที่แห้ง สะอาด อากาศถ่ายเทได้สะดวก ไม่มีแสงแดดส่องกระทบตัวเครื่องโดยตรงและไม่มีจุดเสี่ยงน้ำรั่วซึม เต้ารับไฟฟ้า AC และสายนำสัญญาณร้อยท่อแนบผนังเข้าจุดจ่ายไฟเป็นระเบียบเรียบร้อย แรงดันไฟฟ้าหลักอยู่ในเกณฑ์ปกติ","antennaCondition":"เสาอากาศโครงเหล็กถัก (Self-Supporting Lattice Mast) ทาสีสลับแดง-ขาว ติดตั้งบนฐานรากคอนกรีตภายนอกอาคาร โครงสร้างเสาตั้งตรง มั่นคงแข็งแรงดี แนวสายนำสัญญาณเดินพาดเข้าสู่ตัวอาคารเรียบร้อย เปลือกหุ้มสายสมบูรณ์ไม่แตกลายงา บ่อพักระบบกราวด์ (Master Ground, AC Ground และจุดต่อลงดิน) สภาพสมบูรณ์พร้อมใช้งาน และตรวจวัดค่าความต้านทานดินผ่านเกณฑ์มาตรฐานทุกจุด","workObstacle":"ไม่มีอุปสรรค การเดินทางเข้าพื้นที่สะดวก เจ้าของพื้นที่ให้ความร่วมมือและอำนวยความสะดวกในการเข้าตรวจเช็กอุปกรณ์ ตรวจวัดระบบไฟฟ้า และจุดทดสอบระบบกราวด์เป็นอย่างดี","summary":"เจ้าของพื้นที่แจ้งว่าการสื่อสารใช้งานได้ตามปกติ แต่ในช่วงฤดูฝนมักมีเหตุไฟฟ้าตกหรือดับเป็นครั้งคราว ขอให้ระบบสำรองไฟและระบบป้องกันฟ้าผ่ามีความพร้อมทำงานอยู่เสมอ","photos":[],"recordId":"PM-202610160121171-8854"}', NULL);
