INSERT OR REPLACE INTO surveys (record_id, saved_at, updated_at, version, station, province, permit, fields_json, deleted_at) VALUES ('PM-202610160148102-a770', '2026-10-16T01:48:10.275Z', '2026-10-16T01:48:10.275Z', 1, 'BS หนองนกแก้ว', 'กาญจนบุรี', 'อนุญาต', '{"permit":"อนุญาต","radioStatus":"ปกติ","receiveStatus":"ปกติ","transmitStatus":"ปกติ","powerStatus":"ปกติ","batteryStatus":"ปกติ","groundStatus":"ปกติ","station":"BS หนองนกแก้ว","province":"กาญจนบุรี","district":"เลาขวัญ","subdistrict":"หนองนกแก้ว","installationPlace":"อบต.หนองนกแก้ว อ.เลาขวัญ จ.กาญจนบุรี","equipmentPlace":"ตู้ Outdoor Cabinet บนแท่นฐานราก บริเวณโคนเสาทาวเวอร์","contactName":"นายบุญชัย รัตนสิริวัฒนกุล","contactPosition":"หน.ศสปค","contactVillage":"BS หนองนกแก้ว","contactPhone":"0639016600","informantName":"นายบุญชัย รัตนสิริวัฒนกุล","operatorName":"นายวัชระ มานะดี","visitDate":"2026-10-07","siteCondition":"อุปกรณ์สื่อสารหลัก สวิตช์เครือข่าย ระบบไฟสำรอง (UPS/แบตเตอรี่ลิเธียม Vision 48V) ติดตั้งภายในตู้ Outdoor Cabinet อย่างมั่นคงบนโครงแท่นเหล็กและฐานรากคอนกรีตบริเวณโคนเสา พัดลมระบายความร้อนและ Heat Exchanger ฝาตู้ทำงานปกติ อุณหภูมิภายในตู้เหมาะสม (ประมาณ 31-32°C) ตู้ควบคุมไฟฟ้า AC และอุปกรณ์ Surge Protector ติดตั้งเรียบร้อย ปิดผนึกกันน้ำและความชื้นได้ดี ไม่มีน้ำขังภายในตู้","antennaCondition":"เสาทาวเวอร์โครงเหล็กถัก 4 ขา (4-Leg Self-Supporting Tower) ทาสีสลับแดง-ขาวชัดเจน โครงสร้างเสาตั้งตรง มั่นคงแข็งแรง ไม่พบการทรุดเอียงหรือสนิมผุกร่อนรุนแรง ไฟสัญญาณเตือนการบิน (Aviation Light) บนยอดเสาและสายล่อฟ้าติดตั้งสมบูรณ์ แนวสายนำสัญญาณร้อยยึดแนบกับโครงสร้างเสาเข้าสู่ตู้ควบคุมเรียบร้อย เปลือกหุ้มสายสมบูรณ์ไม่แตกลายงา บ่อพักระบบกราวด์ (Master Ground Pit) และ Ground Bar อยู่ในสภาพสมบูรณ์ ค่าความต้านทานดินวัดได้ต่ำกว่า 1 โอห์ม ผ่านเกณฑ์มาตรฐานดีเยี่ยมทุกจุด","workObstacle":"ไม่มีอุปสรรค ทางเข้า-ออกสถานีสะดวก ลานบริเวณโคนเสาเปิดโล่ง สามารถเข้าตรวจเช็กอุปกรณ์ภายในตู้และจุดทดสอบระบบกราวด์ได้สะดวกและปลอดภัย","summary":"เจ้าหน้าที่แจ้งว่าพื้นที่บริเวณสถานีฐานและเสาทาวเวอร์มีการเข้าเวรดูแลความปลอดภัยเป็นประจำ หากมีการตัดหญ้าหรือปรับปรุงภูมิทัศน์รอบลานเสาจะระมัดระวังแนวสายดินและสายสัญญาณ","photos":[],"recordId":"PM-202610160148102-a770"}', NULL);
INSERT OR REPLACE INTO surveys (record_id, saved_at, updated_at, version, station, province, permit, fields_json, deleted_at) VALUES ('PM-202610160151493-85cc', '2026-10-16T01:52:36.816Z', '2026-10-16T01:52:36.816Z', 1, 'ที่ว่าการอำเภอห้วยกระเจา', 'กาญจนบุรี', 'อนุญาต', '{"permit":"อนุญาต","radioStatus":"ปกติ","receiveStatus":"ปกติ","transmitStatus":"ปกติ","powerStatus":"ปกติ","batteryStatus":"ปกติ","groundStatus":"ปกติ","station":"ที่ว่าการอำเภอห้วยกระเจา","province":"กาญจนบุรี","district":"ห้วยกระเจา","subdistrict":"ห้วยกระเจา","installationPlace":"ที่ว่าการอำเภอห้วยกระเจา เลขที่ 399 ถนนบ่อพลอย-อู่ทอง หมู่ที่ 6 ตำบลห้วยกระเจา อำเภอห้วยกระเจา จังหวัดกาญจนบุรี 71170","equipmentPlace":"ตู้ควบคุมภายนอกอาคาร (Outdoor Cabinet) บริเวณลานสถานีฐาน AGW ห้วยกระเจา","contactName":"นายบุญชัย รัตนสิริวัฒนกุล","contactPosition":"หน.ศสปค","contactVillage":"ที่ว่าการอำเภอห้วยกระเจา","contactPhone":"0639016600","visitDate":"2026-10-05","siteCondition":"อุปกรณ์วิทยุสื่อสารสถานีฐาน Hytera (AGW01-RADIO01 / RADIO02), สวิตช์เครือข่าย และระบบสำรองไฟ (UPS Syndome) ติดตั้งภายในตู้ Outdoor Cabinet อย่างมั่นคงบนแท่นโครงเหล็กเหนือฐานรากคอนกรีตบริเวณลานโคนเสา สภาพภายในตู้แห้ง สะอาด การจัดเก็บสายนำสัญญาณและสายไฟเป็นระเบียบเรียบร้อย ยางขอบตู้และระบบพัดลมระบายความร้อนฝาตู้ทำงานสมบูรณ์ ไม่มีปัญหาน้ำรั่วซึมหรือความชื้นสะสม","antennaCondition":"เสาทาวเวอร์โครงเหล็กถัก 4 ขา (4-Leg Self-Supporting Tower) ทาสีสลับแดง-ขาวชัดเจน โครงสร้างเสาตั้งตรง มั่นคงแข็งแรง ไม่พบสนิมกัดกร่อนหรือการทรุดเอียง สายล่อฟ้าและไฟเตือนการบินบนยอดเสาติดตั้งเรียบร้อย สายนำสัญญาณยึดแนบกับโครงสร้างเสาเข้าสู่ตู้ควบคุมอย่างแน่นหนา เปลือกหุ้มสายสมบูรณ์ไม่แตกลายงา แม้บริเวณรอบพื้นที่จะมีแนวต้นไม้ แต่ระยะห่างจากโครงสร้างเสาและสายอากาศอยู่ในเกณฑ์ปลอดภัย","workObstacle":"ไม่มีอุปสรรค ทางเข้า-ออกพื้นที่สถานีสะดวก ลานบริเวณโคนเสาเปิดโล่ง สามารถเปิดตู้เพื่อตรวจเช็กอุปกรณ์ วิทยุสื่อสาร และระบบไฟฟ้าได้อย่างสะดวกและปลอดภัย","summary":"เจ้าหน้าที่แจ้งว่าพื้นที่บริเวณสถานีฐานมีการตรวจสอบและดูแลความเรียบร้อยเป็นประจำ หากมีการตัดแต่งกิ่งไม้หรือปรับปรุงภูมิทัศน์รอบลานเสา จะระมัดระวังไม่ให้กระทบต่อแนวสายดินและสายสัญญาณ","informantName":"นายบุญชัย รัตนสิริวัฒนกุล","operatorName":"นายวัชระ มานะดี","photos":[],"visitTime":"","accessLimit":"","userProblem":"","recordId":"PM-202610160151493-85cc"}', NULL);
