INSERT OR REPLACE INTO surveys (record_id, saved_at, updated_at, version, station, province, permit, fields_json, deleted_at) VALUES ('PM-202610160206050-730b', '2026-10-16T02:06:05.068Z', '2026-10-16T02:06:05.068Z', 1, 'หมู่ 9 ดงรัง', 'กาญจนบุรี', 'อนุญาต', '{"permit":"อนุญาต","radioStatus":"ปกติ","receiveStatus":"ปกติ","transmitStatus":"ปกติ","powerStatus":"ปกติ","batteryStatus":"ปกติ","groundStatus":"ปกติ","station":"หมู่ 9 ดงรัง","province":"กาญจนบุรี","district":"ห้วยกระเจา","subdistrict":"สระลงเรือ","installationPlace":"ที่ทำการบ้านผู้ใหญ่บ้าน","equipmentPlace":"ที่ทำการบ้านผู้ใหญ่บ้าน","contactName":"นายสุพรรณ นวกวงศ์","contactPosition":"ผู้ใหญ่บ้าน","contactVillage":"หมู่ 9 ดงรัง","contactPhone":"089-746-7955","visitDate":"2026-10-06","informantName":"นายสุพรรณ นวกวงศ์","operatorName":"นายวัชระ มานะดี","siteCondition":"อุปกรณ์วิทยุสื่อสาร Hytera จัดวางบนชั้นไม้ 3 ชั้นภายในอาคารอย่างมั่นคง วางอยู่ติดกับตู้เย็น ด้านล่างจัดวางแบตเตอรี่สำรอง (Transpower) ผนังห้องเป็นบล็อกช่องลมระบายอากาศ อากาศถ่ายเทได้สะดวก พื้นที่แห้ง ไม่มีจุดเสี่ยงน้ำรั่วซึม ตู้ควบคุมระบบไฟ AC (POWERSAFE) และเต้ารับไฟฟ้า กสทช. ติดตั้งบนผนังเหนือชั้นวางอย่างเป็นระเบียบเรียบร้อย แรงดันไฟฟ้าและระบบกราวด์ปกติสมบูรณ์","antennaCondition":"เสาอากาศโครงเหล็กทาสีสลับแดง-ขาว ติดตั้งบนฐานรากภายนอกอาคารบริเวณลานข้างบ้าน โครงสร้างเสาตั้งตรง มั่นคงแข็งแรง ไม่พบสนิมหรือการทรุดเอียง แนวสายนำสัญญาณเดินเข้าสู่อาคารเรียบร้อย เปลือกหุ้มสายสมบูรณ์ไม่แตกลายงา แนวกิ่งไม้และสิ่งปลูกสร้างข้างเคียงไม่กีดขวางหรือพาดทับโครงสร้างเสาอากาศ","workObstacle":"ไม่มีอุปสรรค เจ้าของพื้นที่ให้ความร่วมมือและอำนวยความสะดวกในการเข้าตรวจสอบอุปกรณ์ การวัดระบบไฟฟ้า แบตเตอรี่ และการทดสอบสัญญาณวิทยุสื่อสารเป็นอย่างดี","summary":"เจ้าของพื้นที่แจ้งว่าระบบวิทยุสื่อสารใช้งานรับ-ส่งสัญญาณได้ชัดเจนดีมาก (ระดับสัญญาณ -67 dBm) ระบบไฟฟ้าและแบตเตอรี่สำรองทำงานได้สมบูรณ์ ไม่พบปัญหาขัดข้อง และไม่มีข้อร้องเรียนเพิ่มเติม","photos":[],"recordId":"PM-202610160206050-730b"}', NULL);
